#!/usr/bin/env -S deno run --allow-read --allow-write
// sync-shared.ts — copy the shared money modules from their ONE source in
// supabase/supabase/functions/_shared/ into packages/place-profile/src/.
//
// CONTRACT (MESITA-3302):
//   _shared/money-state.ts   = SOURCE. What a place sells, whether cashback
//                              applies, how a guest can pay. Hand-edited.
//   _shared/money-codes.ts   = SOURCE. Every code a money EF answers with.
//   packages/place-profile/src/money-state.ts, money-codes.ts
//                            = FULLY GENERATED byte-identical copies.
//
// Why copy instead of import: the monorepo has NO root pnpm workspace on
// purpose (each package is its own install root), so there is no import
// path the package can reach. Same idiom as sync-rules.ts and sync-brand.ts:
// generate, and gate with --check in CI. The twins import nothing, so the
// same bytes compile under Deno and under the package's TypeScript.
//
// Run from the repo root:
//     deno task sync-shared
// Pass --check to verify without writing (STRICT: any drift exits 1).
// money-twins.test.ts in _shared pins the same equality from the Deno side.

import { dirname, fromFileUrl, join } from "@std/path";

const repoRoot = dirname(dirname(fromFileUrl(import.meta.url)));
const check = Deno.args.includes("--check");

const SOURCE_DIR = "supabase/supabase/functions/_shared";
const TARGET_DIR = "packages/place-profile/src";
export const TWINS = ["money-state.ts", "money-codes.ts"] as const;

let drift = 0;
for (const name of TWINS) {
  const source = join(repoRoot, SOURCE_DIR, name);
  const target = join(repoRoot, TARGET_DIR, name);
  const want = await Deno.readTextFile(source);
  let have: string | null = null;
  try {
    have = await Deno.readTextFile(target);
  } catch {
    have = null;
  }
  if (have === want) continue;
  if (check) {
    console.error(`DRIFT: ${TARGET_DIR}/${name} ${have === null ? "is missing" : "differs from"} ${SOURCE_DIR}/${name}`);
    drift++;
    continue;
  }
  await Deno.writeTextFile(target, want);
  console.log(`wrote ${TARGET_DIR}/${name}`);
}

if (check) {
  if (drift > 0) {
    console.error(`${drift} shared module(s) out of sync — run: deno task sync-shared`);
    Deno.exit(1);
  }
  console.log(`shared modules in sync (${TWINS.length})`);
}
